    /// Specify the key-value pairs for the tags that you want to attach to your knowledge base in this object. key -&gt; (string) Constraints: o min: 1 o max: 128 o pattern: [a-zA-Z0-9\s._:/=+@-]* value -&gt; (string) Constraints: o min: 0 o max: 256 o pattern: [a-zA-Z0-9\s._:/=+@-]* Shorthand Syntax: KeyName1=string,KeyName2=string JSON Syntax: {"string": "string" ...}
    /// </summary>
    [CliOption("--tags", CollectionSeparator = ",")]
